head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil01085";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — resultVo, formKey, keyValue, returnKey

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil01085.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_if_12", fn: function(){ return ((((dma_pageContext.get("resultVo") ?? "")) && typeof ((dma_pageContext.get("resultVo") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("resultVo") ?? "")).getRowCount() : ((((dma_pageContext.get("resultVo") ?? "")) == null) ? 0 : (((dma_pageContext.get("resultVo") ?? "")).length || 0))) > 0); } }, { id: "tr_14", fn: function(){ return ((((dma_pageContext.get("resultVo") ?? "")) && typeof ((dma_pageContext.get("resultVo") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("resultVo") ?? "")).getRowCount() : ((((dma_pageContext.get("resultVo") ?? "")) == null) ? 0 : (((dma_pageContext.get("resultVo") ?? "")).length || 0))) > 0); } }, { id: "c_if_28", fn: function(){ return ((((dma_pageContext.get("resultVo") ?? "")) && typeof ((dma_pageContext.get("resultVo") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("resultVo") ?? "")).getRowCount() : ((((dma_pageContext.get("resultVo") ?? "")) == null) ? 0 : (((dma_pageContext.get("resultVo") ?? "")).length || 0))) === 0); } }, { id: "tr_30", fn: function(){ return ((((dma_pageContext.get("resultVo") ?? "")) && typeof ((dma_pageContext.get("resultVo") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("resultVo") ?? "")).getRowCount() : ((((dma_pageContext.get("resultVo") ?? "")) == null) ? 0 : (((dma_pageContext.get("resultVo") ?? "")).length || 0))) === 0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_searchYn", fn: function () { return String(String((dma_pageContext.get("searchYn") ?? ""))); } },
        { childId: "ipt_formKey", fn: function () { return String(String((dma_pageContext.get("formKey") ?? ""))); } },
        { childId: "ipt_keyValue", fn: function () { return String(String((dma_pageContext.get("keyValue") ?? ""))); } },
        { childId: "ipt_returnKey", fn: function () { return String(String((dma_pageContext.get("returnKey") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldfil01085: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_noSelected_onclick
 * @description 「-|-」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_noSelected_onclick = function(e){
    try {
        scwin.noSelected()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil01085.ipt_noSelected_onclick' }); }
};

/**
 * @method
 * @name btn_selected_onclick
 * @description btn_selected 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_selected_onclick = async function(e){
    try {
        await scwin.selected()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil01085.btn_selected_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil01085.btn_self_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name selected
 * @description selected 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selected = async function () {
    let ndx = "";
    const selectArr = new Array(2);
    let code = "";
    let name = "";
    const obj = ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).Potential).Provider;
    const frameId = obj.ActiveFrame.FrameID;
    const frame = obj.Provider(frameId).ActiveFrame;
    if (($c.util.getComponent('ipt_noSelected').getValue() != null && String($c.util.getComponent('ipt_noSelected').getValue()) !== '') === false) {
        for (i = 0; i < $c.util.getComponent("slc_selIndcode").length; i++) {
            if ($c.util.getComponent("slc_selIndcode").options[i].selected) {
                if (name.length === "") {
                    name = $c.util.getComponent("slc_selIndcode").options[i].text;
                    code = $c.util.getComponent("slc_selIndcode").options[i].value;
                } else {
                    name = name + "," + $c.util.getComponent("slc_selIndcode").options[i].text;
                    code = code + "," + $c.util.getComponent("slc_selIndcode").options[i].value;
                }
                ndx++;
            }
        }
        if (ndx === 0) {
            await $c.win.alert("입력할 사유를  선택하십시오");
            return;
        } else {
            frame.fn_setSelectedData((String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), code, name);
            $c.win.closePopup();
        }
    } else {
        code = "-";
        name = "-";
        frame.fn_setSelectedData((String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("keyValue") ?? "")) == null ? '' : ((dma_pageContext.get("keyValue") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), code, name);
        $c.win.closePopup();
    }
};

/**
 * @method
 * @name noSelected
 * @description no Selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.noSelected = function () {
    if ($c.util.getComponent("ipt_searchYn").getValue() === 'Y') {
        if (($c.util.getComponent('ipt_noSelected').getValue() != null && String($c.util.getComponent('ipt_noSelected').getValue()) !== '') === true) {
            $c.util.getComponent('slc_selIndcode').setDisabled(true);
        } else {
            $c.util.getComponent('slc_selIndcode').setDisabled(false);
        }
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
